import{_ as o,o as t,c as a,a3 as i}from"./chunks/framework.DhF4LrUq.js";const s="/shipperdog/snapshot/screenshots/console-abac.png",g=JSON.parse('{"title":"Author ABAC policies","description":"Author ABAC policies - DENY and REQUIRE rules that narrow access by application, environment, and ring, with versioned history.","frontmatter":{"description":"Author ABAC policies - DENY and REQUIRE rules that narrow access by application, environment, and ring, with versioned history."},"headers":[],"relativePath":"how-to/console/abac-policies.md","filePath":"how-to/console/abac-policies.md"}'),r={name:"how-to/console/abac-policies.md"};function n(l,e,c,h,d,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="author-abac-policies" tabindex="-1">Author ABAC policies <a class="header-anchor" href="#author-abac-policies" aria-label="Permalink to &quot;Author ABAC policies&quot;">​</a></h1><p>Attribute-based access control is the fine-grained layer <em>above</em> roles: while roles say what kind of act you may perform, ABAC rules say under which conditions any act happens at all. The <strong>Access policies</strong> screen authors them as data — versioned, ordered, and audited.</p><p><img src="'+s+'" alt="The Access policies screen"></p><p>Where ABAC sits in the full decision chain is covered in <a href="/shipperdog/snapshot/concepts/authorization">authorization</a>.</p><div class="warning custom-block"><p class="custom-block-title">Both effects only ever narrow</p><p><code>DENY</code> blocks outright; <code>REQUIRE</code> demands a condition hold. Neither can <em>grant</em> anything a role did not already allow — ABAC is a one-way ratchet toward less access, never more.</p></div><h2 id="create-a-policy" tabindex="-1">Create a policy <a class="header-anchor" href="#create-a-policy" aria-label="Permalink to &quot;Create a policy&quot;">​</a></h2><ol><li><p>Open <strong>Access policies</strong> and click <strong>New policy</strong>.</p></li><li><p>Give it a <strong>Name</strong> and pick the <strong>Effect</strong>:</p><ul><li><strong>DENY (refuse when it holds)</strong> — when the condition holds, the act is refused.</li><li><strong>REQUIRE (must hold)</strong> — when the scoped act happens, the condition must hold or it is refused.</li></ul></li><li><p>Pick the <strong>Action</strong> the rule governs — <code>PROMOTE</code> (ring hops), <code>DOWNLOAD</code>, <code>READ_ARTIFACT</code>, or <code>LIST_APPLICATIONS</code>.</p></li><li><p>Scope the rule — any field left empty means <em>any</em>:</p><ul><li><strong>Application (any if empty)</strong></li><li><strong>Environment (any if empty)</strong></li><li><strong>Ring (any if empty)</strong></li></ul></li><li><p>Set the <strong>Position (order)</strong> — rules evaluate in this order, so an early DENY wins before anything later runs.</p></li><li><p>Write the <strong>Condition (JSON)</strong> — the typed condition editor. The one-click template seeds a working example; the client checks that the JSON parses (a syntax gate — the server&#39;s own validation is the authority, and its field errors surface inline).</p></li><li><p>Save. <strong>Save policy</strong> writes the rule; references (the application, environment, or ring it names) resolve server-side at write time — a rule naming an unknown ring is refused, not silently dead.</p></li></ol><h2 id="manage-the-rule-set" tabindex="-1">Manage the rule set <a class="header-anchor" href="#manage-the-rule-set" aria-label="Permalink to &quot;Manage the rule set&quot;">​</a></h2><ul><li><strong>Edit</strong> reopens the dialog; each save creates a new <em>version</em> of the policy — nothing is overwritten.</li><li><strong>Version history</strong> (per policy) lists every version with its enabled state.</li><li>The <strong>Enabled</strong> switch in the editor parks a rule without deleting it; a disabled chip marks parked rows in the list.</li></ul><h2 id="a-worked-shape" tabindex="-1">A worked shape <a class="header-anchor" href="#a-worked-shape" aria-label="Permalink to &quot;A worked shape&quot;">​</a></h2><p>The classic production guard — &quot;promotions into production require the release to carry no open critical findings&quot; — becomes a <code>REQUIRE</code> rule scoped to the <code>production</code> ring, and a quarantine shape — &quot;the suspended tenant sees nothing&quot; — a <code>DENY</code> rule scoped to that tenant&#39;s context. Compose narrow rules over broad ones; each is audited when it fires.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/sso-oidc-saml">SSO setup</a> · <a href="/shipperdog/snapshot/how-to/console/siem-streams">SIEM streams</a> · <a href="/shipperdog/snapshot/concepts/authorization">authorization concepts</a></p>',12)])])}const m=o(r,[["render",n]]);export{g as __pageData,m as default};
